import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"단축키 설정","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 전역 (Global)","slug":"_1-전역-global","link":"#_1-전역-global","children":[{"level":3,"title":"전역 단축키 그룹","slug":"전역-단축키-그룹","link":"#전역-단축키-그룹","children":[]},{"level":3,"title":"기능 키 그룹","slug":"기능-키-그룹","link":"#기능-키-그룹","children":[]},{"level":3,"title":"퀵 내비게이션 마우스 트리거 그룹","slug":"퀵-내비게이션-마우스-트리거-그룹","link":"#퀵-내비게이션-마우스-트리거-그룹","children":[]},{"level":3,"title":"단축키 입력하기","slug":"단축키-입력하기","link":"#단축키-입력하기","children":[]},{"level":3,"title":"즐겨찾기 항목별 단축키","slug":"즐겨찾기-항목별-단축키","link":"#즐겨찾기-항목별-단축키","children":[]}]},{"level":2,"title":"2. 플러그인 액션 (Plugin Actions)","slug":"_2-플러그인-액션-plugin-actions","link":"#_2-플러그인-액션-plugin-actions","children":[]},{"level":2,"title":"3. 프로세스 블랙리스트 (Process Blacklist)","slug":"_3-프로세스-블랙리스트-process-blacklist","link":"#_3-프로세스-블랙리스트-process-blacklist","children":[]}],"relativePath":"ko-KR/user-guide/settings/hotkeys-page.md","filePath":"ko-KR/user-guide/settings/hotkeys-page.md","lastUpdated":1791112464000}'),s={name:"ko-KR/user-guide/settings/hotkeys-page.md"};function i(n,o,a,c,d,g){return t(),l("div",null,[...o[0]||(o[0]=[r('<h1 id="단축키-설정" tabindex="-1">단축키 설정 <a class="header-anchor" href="#단축키-설정" aria-label="Permalink to &quot;단축키 설정&quot;">​</a></h1><p>단축키 설정 페이지에서는 Lertaro의 모든 전역 호출 키, 앱 내 탐색 단축키, 플러그인 액션 바로가기 및 프로세스 블랙리스트 규칙을 통합 관리합니다. 상단에는 <strong>전역</strong>, <strong>플러그인 액션</strong>, <strong>프로세스 블랙리스트</strong>의 3개 탭이 제공됩니다.</p><h2 id="_1-전역-global" tabindex="-1">1. 전역 (Global) <a class="header-anchor" href="#_1-전역-global" aria-label="Permalink to &quot;1. 전역 (Global)&quot;">​</a></h2><h3 id="전역-단축키-그룹" tabindex="-1">전역 단축키 그룹 <a class="header-anchor" href="#전역-단축키-그룹" aria-label="Permalink to &quot;전역 단축키 그룹&quot;">​</a></h3><ul><li><strong>퀵 검색 표시/숨기기</strong>: 전용 키 녹화 컨트롤. <strong>수식키 더블 클릭 모드</strong>(기본값 <code>Ctrl</code> 더블 클릭, <code>Alt</code>나 <code>Shift</code>로도 가능) 및 <strong>일반 조합키</strong>(예: <code>Alt+Space</code> 등)를 모두 지원합니다.</li><li><strong>전체 패널을 기본으로 열기</strong>: 체크박스(기본 비활성화). 켜면 전역 호출 단축키가 퀵 윈도우 대신 메인 윈도우를 엽니다. 처음 표시될 때는 한 번만 전경 및 포커스를 처리하고, 표시되어 있지만 비활성 상태이면 다시 활성화하며, 이미 활성 상태이면 기본적으로 다시 눌렀을 때 퀵 윈도우로 돌아가고 <strong>단축키 재입력 시 전체 창 닫기</strong>가 켜져 있을 때만 바로 닫습니다. 창을 자동으로 항상 위에 유지하지는 않습니다.</li><li><strong>전체화면 앱 포커스 시에도 응답</strong>: 체크박스(기본 비활성화). 켜면 전체화면 게임이나 동영상 재생기가 활성화되어 있어도 단축키에 응답하며, 끄면 게임 플레이를 보호하기 위해 단축키를 통과시킵니다.</li><li><strong>퀵 점프 (Quick Jump)</strong>: 기본값 <code>Ctrl+G</code>. 파일 대화상자에서 최근 탐색했던 폴더로 즉시 이동합니다.</li><li><strong>퀵 내비게이션 메뉴</strong>: 기본 단축키 없음. 선택한 전역 단축키를 지정해 계층형 메뉴를 열 수 있습니다. 바탕화면이나 일반 앱에서는 바탕화면 컨텍스트를 사용하고, 파일 탐색기와 네이티브 파일 대화상자에서는 현재 창 컨텍스트를 사용합니다. 일반 전경 보호로 전역 단축키가 억제되는 경우에도 파일 관리자와 파일 대화상자는 허용됩니다.</li></ul><h3 id="기능-키-그룹" tabindex="-1">기능 키 그룹 <a class="header-anchor" href="#기능-키-그룹" aria-label="Permalink to &quot;기능 키 그룹&quot;">​</a></h3><p>임의의 단일 키 또는 조합키를 지정할 수 있는 독립 녹화 컨트롤을 제공합니다.</p><ul><li><strong>다음 / 이전 항목 선택</strong>: 기본값 <code>Ctrl+N</code> / <code>Ctrl+P</code>(방향키 <code>↓</code> / <code>↑</code>와 동일).</li><li><strong>결과 이동 수식키</strong>: 기본값 <code>Ctrl</code>, 숫자키 <code>1</code>–<code>9</code>와 조합하여 즉시 실행.</li><li><strong>액션 메뉴 열기</strong>: 기본값 <code>Ctrl+O</code>(방향키 <code>→</code>와 동일). 두 키 모두 퀵 윈도우와 파일 대화상자 밖의 인라인 카드에 적용되며, 메인 윈도우에서는 우클릭 또는 <code>Apps</code> 키로 같은 메뉴를 엽니다.</li><li><strong>선택 항목으로 검색어 자동완성</strong>: 기본값 <code>Ctrl+Tab</code>.</li><li><strong>QuickLook 즉시 미리보기</strong>: 기본값 <code>Alt+P</code>.</li><li><strong>이전 / 다음 검색 기록어</strong>: 기본값 <code>Alt+Up</code> / <code>Alt+Down</code>.</li><li><strong>현재 검색 기록어 삭제</strong>: 기본값 <code>Ctrl+Delete</code>.</li><li><strong>메인 윈도우 열기</strong>: 기본값 <code>Ctrl+F</code>.</li><li><strong>LocalSend 창 열기</strong>: 기본값 <code>Ctrl+S</code>.</li><li><strong>창 고정 (항상 유지)</strong>: 기본값 <code>Ctrl+T</code>.</li><li><strong>퀵 패널 표시/숨기기</strong>: 기본값 <code>Ctrl+F2</code>.</li></ul><h3 id="퀵-내비게이션-마우스-트리거-그룹" tabindex="-1">퀵 내비게이션 마우스 트리거 그룹 <a class="header-anchor" href="#퀵-내비게이션-마우스-트리거-그룹" aria-label="Permalink to &quot;퀵 내비게이션 마우스 트리거 그룹&quot;">​</a></h3><ul><li><strong>빈 공간 좌클릭 더블클릭</strong>: 체크박스(<strong>기본 비활성화</strong>). 바탕화면이나 탐색기 빈 공간 더블클릭 시 메뉴 표시.</li><li><strong>빈 공간 휠클릭</strong>: 체크박스(기본 활성화). 바탕화면, 탐색기 또는 파일 대화상자에서 휠클릭 시 메뉴 표시.</li></ul><p>더블클릭 방식은 바탕화면과 파일 탐색기에서만 작동하며, 서드파티 파일 관리자는 휠클릭만 인식합니다. 포인터가 Lertaro 자체 카드 위에 있는 동안에는 두 트리거 모두 건너뛰고, 블랙리스트나 전체화면 때문에 전역 트리거가 침묵할 때에도 파일 관리자와 대화상자에서는 두 트리거가 계속 동작합니다.</p><h3 id="단축키-입력하기" tabindex="-1">단축키 입력하기 <a class="header-anchor" href="#단축키-입력하기" aria-label="Permalink to &quot;단축키 입력하기&quot;">​</a></h3><p>어떤 키를 누르든 뒤의 앱이 아니라 입력 상자에 기록되므로, 입력 상자 자체에도 제스처가 있습니다.</p><ul><li><strong><code>Escape</code></strong>: 입력을 취소하면서 값을 지웁니다. &quot;취소하고 되돌리기&quot;는 없습니다. 누르는 순간 상자가 비어 있습니다.</li><li><strong><code>✕</code></strong>: 상자를 지웁니다. <strong><code>↺</code></strong>: 그 행의 제조사 기본값을 복원합니다. 두 버튼은 항상 그중 하나만 보입니다: 조합이 입력되어 있으면 지우기, 비어 있으면 복원이 표시됩니다.</li><li><strong>수식키 단독 입력</strong>(<code>Ctrl</code>, <code>Alt</code>, <code>Shift</code>): 그것만으로 의미가 있는 행에서만 허용됩니다. 더블 클릭 방식이 되는 호출 단축키와 결과 이동 수식키가 그렇습니다. 일반 조합키 행에서 수식키만 누르고 놓으면 절대 실행될 수 없는 값을 저장하는 대신 그 행이 <strong>지워집니다</strong>.</li><li><strong>Windows 예약 조합</strong>(<code>Win+E</code>, <code>Win+D</code> 등)은 거부됩니다: 값이 강제로 비워지므로 상자가 그대로 빈 상태가 됩니다.</li><li><strong>충돌 감지는 없습니다.</strong> 두 행이 같은 조합을 가져도 경고하지 않으며, 즐겨찾기 항목 단축키에서만 중복 또는 OS가 거부한 조합을 알려 주고, 그것도 적용한 뒤에 알려 줍니다.</li></ul><h3 id="즐겨찾기-항목별-단축키" tabindex="-1">즐겨찾기 항목별 단축키 <a class="header-anchor" href="#즐겨찾기-항목별-단축키" aria-label="Permalink to &quot;즐겨찾기 항목별 단축키&quot;">​</a></h3><p>각 즐겨찾기(<a href="./favorites.html"><strong>설정 → 즐겨찾기</strong></a>)는 자체 <strong>OS 레벨 전역</strong> 단축키를 가질 수 있습니다. Lertaro 창이 하나도 열려 있지 않을 때도 작동하며, 전경 파일 관리자를 해당 폴더로 이동시킵니다. 위의 입력 상자와 달리 반드시 수식키가 필요하고, 수식키 단독은 허용되지 않으며, <code>F12</code>는 사용할 수 없습니다.</p><h2 id="_2-플러그인-액션-plugin-actions" tabindex="-1">2. 플러그인 액션 (Plugin Actions) <a class="header-anchor" href="#_2-플러그인-액션-plugin-actions" aria-label="Permalink to &quot;2. 플러그인 액션 (Plugin Actions)&quot;">​</a></h2><p>각 플러그인이 등록한 전용 액션 단축키(예: 경로 복사 <code>Ctrl+Shift+C</code>, 이름 복사 <code>Shift+C</code>, 잘라내기 <code>Ctrl+X</code>, 복사 <code>Ctrl+C</code>, 붙여넣기 <code>Ctrl+V</code>, 삭제 <code>Delete</code>, 영구 삭제 <code>Shift+Delete</code> 등)가 여기에 모여 있습니다.</p><ul><li><strong>플러그인별 그룹화</strong>: 제공 플러그인별로 깔끔하게 정리되어 있습니다.</li><li><strong>개별 재등록</strong>: 각 액션마다 전용 녹화 상자가 제공되어 새 키를 입력해 즉시 변경할 수 있습니다.</li></ul><h2 id="_3-프로세스-블랙리스트-process-blacklist" tabindex="-1">3. 프로세스 블랙리스트 (Process Blacklist) <a class="header-anchor" href="#_3-프로세스-블랙리스트-process-blacklist" aria-label="Permalink to &quot;3. 프로세스 블랙리스트 (Process Blacklist)&quot;">​</a></h2><p>특정 프로그램이 활성화되었을 때 Lertaro의 단축키와 마우스 제스처를 무시하도록 설정합니다.</p><ul><li><strong>대소문자 무관</strong>: <code>game.exe</code> 또는 <code>game</code> 모두 지원합니다.</li><li><strong>개별 추가</strong>: 프로세스 이름을 입력하고 <strong>프로세스 추가</strong>를 클릭합니다.</li><li><strong>일괄 관리</strong>: <strong>텍스트 생성</strong>을 눌러 현재 목록을 내보내거나, 붙여넣은 후 <strong>목록에 적용</strong>을 눌러 일괄 갱신할 수 있습니다.</li><li><strong>파일 대화상자 자동 예외</strong>: 블랙리스트 앱이라 하더라도 표준 파일 선택 대화상자가 열리면 인라인 검색 및 퀵 내비게이션이 정상 작동합니다.</li></ul>',22)])])}const p=e(s,[["render",i]]);export{u as __pageData,p as default};
